// From https://www.shadertoy.com/view/XdGfRR
vec2 hash22(vec2 p)
{
	uvec2 q = uvec2(ivec2(p))*uvec2(1597334673U, 3812015801U);
	q = (q.x ^ q.y) * uvec2(1597334673U, 3812015801U);
	return vec2(q) * 2.328306437080797e-10;
}

float get_glitch_offset(vec2 uv, float speed)
{
    vec2 grid_size = vec2(15.);
    vec2 uv_p = (uv + floor(mod(iTime, 60.)*speed))*grid_size;

    // Scaling the UV in the y-axis based on random numbers relative to uv.y
    float y_scale = hash22(uv_p.yy).y; 
    vec2 uv_h = hash22(uv_p*vec2(0.,clamp(y_scale, 0., 1.)));

    float offset = uv_h.y;
    return (offset * 2. - 1.);
}

vec4 get_color(vec2 uv)
{
    float intensity = .008;
    float speed = 15.;

    float o = get_glitch_offset(uv, speed)*intensity;
    vec2 uv_g = vec2(uv.x+o, uv.y);
    vec3 shift = vec3(0, -.95, 0)*o;

    vec3 color = vec3(
        texture(iChannel0, uv_g+vec2(shift.r,0)).r,
        texture(iChannel0, uv_g+vec2(shift.g,0)).g,
        texture(iChannel0, uv_g+vec2(shift.b,0)).b
    );
    return vec4(color, 1.);
}

void mainImage(out vec4 O, in vec2 U)
{
    vec2 ires = iResolution.xy;
    vec2 uv = U/ires;

    O = get_color(uv);
}
